1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office - quote", () => {
5	  it("should return a premium of 5 G for a quote with an empty item list", () => {
6	    const scenario = {
7	      customer: { yearsWithMHPCO: 0 },
8	      steps: [{ op: "quote", items: [] }],
9	    };
10	
11	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
12	  });
13	  it("should return a premium of 115 G for a single plain sword (100 base + 10 first insurance + 5 fee)", () => {
14	    const scenario = {
15	      customer: { yearsWithMHPCO: 0 },
16	      steps: [{ op: "quote", items: [{ type: "sword" }] }],
17	    };
18	
19	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
20	  });
21	  it("should use the price list base premium for amulet, staff and potion", () => {
22	    const quoteFor = (type: string) => ({
23	      customer: { yearsWithMHPCO: 0 },
24	      steps: [{ op: "quote", items: [{ type }] }],
25	    });
26	
27	    expect(runScenario(quoteFor("amulet"))).toEqual({
28	      results: [{ premium: 71 }],
29	    });
30	    expect(runScenario(quoteFor("staff"))).toEqual({
31	      results: [{ premium: 93 }],
32	    });
33	    expect(runScenario(quoteFor("potion"))).toEqual({
34	      results: [{ premium: 49 }],
35	    });
36	  });
37	  it("should sum the base premiums of several main items in one quote", () => {
38	    const scenario = {
39	      customer: { yearsWithMHPCO: 0 },
40	      steps: [
41	        {
42	          op: "quote",
43	          items: [{ type: "sword" }, { type: "amulet" }, { type: "potion" }],
44	        },
45	      ],
46	    };
47	
48	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 225 }] });
49	  });
50	  it("should charge 25 G base premium per component (2 runes -> 50 G base)", () => {
51	    const scenario = {
52	      customer: { yearsWithMHPCO: 0 },
53	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
54	    };
55	
56	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
57	  });
58	  it("should charge 60 G base premium for a block of exactly 3 alike components (3 runes)", () => {
59	    const scenario = {
60	      customer: { yearsWithMHPCO: 0 },
61	      steps: [
62	        {
63	          op: "quote",
64	          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
65	        },
66	      ],
67	    };
68	
69	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
70	  });
71	  it("should not apply the block discount for 4 runes (100 G base premium)", () => {
72	    const scenario = {
73	      customer: { yearsWithMHPCO: 0 },
74	      steps: [
75	        {
76	          op: "quote",
77	          items: [
78	            { type: "rune" },
79	            { type: "rune" },
80	            { type: "rune" },
81	            { type: "rune" },
82	          ],
83	        },
84	      ],
85	    };
86	
87	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
88	  });
89	  it("should apply one block plus singles for 7 runes (175 G base premium)", () => {
90	    const scenario = {
91	      customer: { yearsWithMHPCO: 0 },
92	      steps: [{ op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) }],
93	    };
94	
95	    // The spec lists 7 runes as 175 G base premium, i.e. 7 x 25 G. The block
96	    // discount does NOT kick in here (2 blocks + 1 single would be
97	    // 60 + 60 + 25 = 145 G), so a block is only formed when the count of alike
98	    // components is exactly 3.
99	    // Rounding is a later test, so we assert the exact unrounded premium the
100	    // current pipeline produces from a 175 G base: 175 * 1.1 + 5 = 197.5.
101	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 197.5 }] });
102	  });
103	  it("should not form a block from different component types (2 runes + 1 moonstone -> 75 G base)", () => {
104	    const scenario = {
105	      customer: { yearsWithMHPCO: 0 },
106	      steps: [
107	        {
108	          op: "quote",
109	          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
110	        },
111	      ],
112	    };
113	
114	    // 3 components but not alike, so no block: 3 x 25 G = 75 G base.
115	    // 75 * 1.1 + 5 = 87.5 (rounding is a later test).
116	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 87.5 }] });
117	  });
118	  it("should form two separate blocks for 3 runes + 3 moonstones (120 G base premium)", () => {
119	    const scenario = {
120	      customer: { yearsWithMHPCO: 0 },
121	      steps: [
122	        {
123	          op: "quote",
124	          items: [
125	            { type: "rune" },
126	            { type: "rune" },
127	            { type: "rune" },
128	            { type: "moonstone" },
129	            { type: "moonstone" },
130	            { type: "moonstone" },
131	          ],
132	        },
133	      ],
134	    };
135	
136	    // Two separate blocks of exactly 3 alike components: 60 + 60 = 120 G base.
137	    // 120 * 1.1 + 5 = 137.
138	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 137 }] });
139	  });
140	  it("should not apply the block discount to 3 alike main items (3 swords -> 300 G base premium)", () => {
141	    const scenario = {
142	      customer: { yearsWithMHPCO: 0 },
143	      steps: [
144	        {
145	          op: "quote",
146	          items: [{ type: "sword" }, { type: "sword" }, { type: "sword" }],
147	        },
148	      ],
149	    };
150	
151	    // The block discount applies only to components (rune, moonstone).
152	    // 3 x 100 G = 300 G base; 300 * 1.1 + 5 = 335.
153	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 335 }] });
154	  });
155	  it("should add a 50 % curse surcharge on the base premium of the cursed item", () => {
156	    const scenario = {
157	      customer: { yearsWithMHPCO: 0 },
158	      steps: [{ op: "quote", items: [{ type: "sword", cursed: true }] }],
159	    };
160	
161	    // 100 base + 50 curse surcharge (50 % of that item's base premium)
162	    // + 10 first insurance (10 % of the 100 G policy base premium)
163	    // + 5 processing fee = 165.
164	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 165 }] });
165	  });
166	  it("should apply the curse surcharge only to the cursed item in a multi-item policy (cursed sword + plain amulet -> 210 G before policy modifiers and fee)", () => {
167	    const scenario = {
168	      customer: { yearsWithMHPCO: 0 },
169	      steps: [
170	        {
171	          op: "quote",
172	          items: [{ type: "sword", cursed: true }, { type: "amulet" }],
173	        },
174	      ],
175	    };
176	
177	    // Policy base premium 100 + 60 = 160 G. The curse surcharge is 50 % of the
178	    // cursed sword's own base premium only (50 G), not of the policy base, so
179	    // the running total before policy modifiers and fee is 210 G.
180	    // + 16 first insurance (10 % of the 160 G policy base premium)
181	    // + 5 processing fee = 231.
182	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 231 }] });
183	  });
184	  it.todo("should add a 30 % high-enchantment surcharge for an item with enchantment exactly 5");
185	  it.todo("should not add the high-enchantment surcharge for an item with enchantment 4");
186	  it.todo("should apply both curse and high-enchantment surcharges to the same item");
187	  it.todo("should apply a 20 % loyalty discount on the policy base premium for a customer with exactly 2 years with MHPCO");
188	  it.todo("should not apply the loyalty discount for a customer with 1 year with MHPCO");
189	  it.todo("should apply the 10 % first insurance surcharge on the policy base premium of every quote");
190	  it.todo("should apply a 15 % follow-up discount on the policy base premium for each quote after the customer's first");
191	  it.todo("should add the 5 G processing fee at the very end, after all discounts and surcharges");
192	  it.todo("should round the final premium up (197.5 G -> 198 G) while keeping intermediate values as fractions");
193	  it.todo("should return 165 G for a newcomer with a cursed steel sword of enchantment 3");
194	  it.todo("should return 160 G for a 3-year customer's second quote with a cursed steel sword of enchantment 7");
195	});
196	
197	describe("MHPCO Claim Office - claim", () => {
198	  it.todo("should subtract the 100 G deductible from the damage amount (sword, 500 G damage -> 400 G payout)");
199	  it.todo("should reimburse a component minus the deductible (rune, 200 G damage -> 100 G payout)");
200	  it.todo("should apply the 100 G deductible once per damage entry (sword 500 G + amulet 300 G -> 600 G payout)");
201	  it.todo("should reimburse 50 % before the deductible for an item with enchantment exactly 8 (1000 G damage -> 400 G payout)");
202	  it.todo("should reimburse 50 % before the deductible for an item with enchantment 9 (steel sword, 1000 G damage -> 400 G payout)");
203	  it.todo("should fully reimburse dragon-material items before the deductible (dragon sword enchantment 5, 800 G damage -> 700 G payout)");
204	  it.todo("should let the 50 % high-enchantment rule win over dragon material (dragon sword enchantment 9, 1000 G damage -> 400 G payout)");
205	  it.todo("should treat two damage entries of the same insured item type as separate damages with their own deductible");
206	  it.todo("should report the remaining cap of twice the insurance sum after a claim");
207	  it.todo("should base the cap on the unmodified insurance values, not on the premium (cursed sword -> cap 2000 G)");
208	  it.todo("should base the cap on the unmodified insurance values of components, not on the block discount (sword + 3 runes -> insurance sum 1750 G)");
209	  it.todo("should cap the cumulative payout across successive claims (1500 G then 1500 G on a sword -> 1400 G then 600 G, remaining cap 0 G)");
210	  it.todo("should round the final payout down (350.5 G -> 350 G)");
211	});
212	
213	describe("MHPCO Claim Office - rejected scenarios", () => {
214	  it.todo("should reject a quote containing an item with an unknown type");
215	  it.todo("should reject a claim whose damage entry references an item type not covered by the policy");
216	  it.todo("should reject a claim whose damage entry references an unknown item type");
217	  it.todo("should reject a claim with more damage entries of a type than the policy insures");
218	  it.todo("should reject a claim with a negative damage amount");
219	});
