1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	};
5	
6	export type Step = {
7	  op: string;
8	  items: Item[];
9	};
10	
11	export type Customer = {
12	  yearsWithMHPCO: number;
13	};
14	
15	export type Scenario = {
16	  customer: Customer;
17	  steps: Step[];
18	};
19	
20	export type Result = {
21	  premium: number;
22	};
23	
24	export type ScenarioOutcome = {
25	  results: Result[];
26	};
27	
28	const PROCESSING_FEE = 5;
29	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	// Percentages are applied as the exact fraction `amount * percent / 100`
39	// rather than via a float factor such as `amount * 0.1`, which drifts.
40	const percentOf = (percent: number, amount: number): number =>
41	  (amount * percent) / 100;
42	
43	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
44	const CURSE_SURCHARGE_PERCENT = 50;
45	
46	const firstInsuranceSurchargeOn = (policyBasePremium: number): number =>
47	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
48	
49	// Surcharges attached to a single item are a percentage of that item's own
50	// base premium from the price list (never of the policy base premium).
51	const surchargeForItem = (item: Item): number =>
52	  item.cursed
53	    ? percentOf(CURSE_SURCHARGE_PERCENT, BASE_PREMIUM_BY_TYPE[item.type])
54	    : 0;
55	
56	const itemSurchargesOf = (items: Item[]): number =>
57	  items.reduce((total, item) => total + surchargeForItem(item), 0);
58	
59	const BLOCK_SIZE = 3;
60	const BLOCK_BASE_PREMIUM = 60;
61	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
62	
63	const countByType = (items: Item[]): Map<string, number> => {
64	  const counts = new Map<string, number>();
65	  for (const item of items) {
66	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
67	  }
68	  return counts;
69	};
70	
71	// A group of exactly BLOCK_SIZE alike components forms a block and is charged
72	// a flat BLOCK_BASE_PREMIUM instead of the per-item price list rate. Main
73	// items never form a block.
74	const basePremiumForAlikeItems = (type: string, count: number): number =>
75	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
76	    ? BLOCK_BASE_PREMIUM
77	    : count * BASE_PREMIUM_BY_TYPE[type];
78	
79	const policyBasePremiumOf = (items: Item[]): number =>
80	  [...countByType(items)].reduce(
81	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
82	    0,
83	  );
84	
85	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
86	  const results = scenario.steps.map((step) => {
87	    const policyBasePremium = policyBasePremiumOf(step.items);
88	    const premium =
89	      policyBasePremium +
90	      itemSurchargesOf(step.items) +
91	      firstInsuranceSurchargeOn(policyBasePremium) +
92	      PROCESSING_FEE;
93	    return { premium };
94	  });
95	
96	  return { results };
97	};
